SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
GO
IF SCHEMA_ID(N'rendimiento') IS NOT NULL THROW 51000, 'Schema rendimiento already exists', 1;
EXEC(N'CREATE SCHEMA [rendimiento]');
GO
CREATE TABLE [rendimiento].[DimensionTemas] (
  [IdTema] INT NOT NULL,
  [Tema] NVARCHAR(2048) NOT NULL,
  CONSTRAINT [PK_DimensionTemas] PRIMARY KEY ([IdTema]),
  CHECK ([IdTema] >= 0)
);
GO
INSERT INTO [rendimiento].[DimensionTemas] ([IdTema], [Tema]) VALUES
(1, N'Arabic'),
(2, N'Biology'),
(3, N'Chemistry'),
(4, N'English'),
(5, N'French'),
(6, N'Geology'),
(7, N'History'),
(8, N'IT'),
(9, N'Math'),
(10, N'Quran'),
(11, N'Science'),
(12, N'Spanish');
GO
CREATE TABLE [rendimiento].[DimensionSemestres] (
  [CodigoSemestre] NVARCHAR(100) NOT NULL,
  [NombreSemestre] NVARCHAR(2048) NOT NULL,
  [IdSemestre] INT NOT NULL,
  CONSTRAINT [PK_DimensionSemestres] PRIMARY KEY ([IdSemestre]),
  CONSTRAINT [UQ_CodigoSemestre] UNIQUE ([CodigoSemestre]),
  CHECK ([IdSemestre] >= 0),
  CHECK ([IdSemestre] IN (1,2)),
  CHECK ([CodigoSemestre] IN (N'F',N'S'))
);
GO
INSERT INTO [rendimiento].[DimensionSemestres] ([CodigoSemestre], [NombreSemestre], [IdSemestre]) VALUES
(N'F', N'First', 1),
(N'S', N'Second', 2);
GO
