CREATE TABLE [rendimiento].[DimensionPeriodosNotas] (
  [PeriodoAcademico] NVARCHAR(100) NOT NULL,
  [AnioAcademico] INT NOT NULL,
  [Semestre] INT NOT NULL,
  CONSTRAINT [PK_DimensionPeriodosNotas] PRIMARY KEY ([PeriodoAcademico]),
  CHECK ([AnioAcademico] >= 0),
  CHECK ([Semestre] >= 0),
  CHECK ([Semestre] IN (1,2))
);
