CREATE TABLE [rendimiento].[HechosObservaciones] (
  [IdObservacion] INT NOT NULL,
  [Genero] NVARCHAR(2048) NOT NULL,
  [Nacionalidad] NVARCHAR(2048) NOT NULL,
  [LugarNacimiento] NVARCHAR(2048) NOT NULL,
  [NivelEducativo] NVARCHAR(2048) NOT NULL,
  [GradoEscolar] NVARCHAR(2048) NOT NULL,
  [Seccion] NVARCHAR(2048) NOT NULL,
  [ParentescoResponsable] NVARCHAR(2048) NOT NULL,
  [VecesManoLevantada] INT NOT NULL,
  [RecursosVisitados] INT NOT NULL,
  [AnunciosVistos] INT NOT NULL,
  [ParticipacionesDiscusion] INT NOT NULL,
  [ResponsableRespondioEncuesta] NVARCHAR(2048) NOT NULL,
  [SatisfaccionEscolarResponsable] NVARCHAR(2048) NOT NULL,
  [CategoriaAusencias] NVARCHAR(2048) NOT NULL,
  [CategoriaRendimiento] NVARCHAR(2048) NOT NULL,
  [IdTema] INT NOT NULL,
  [IdSemestre] INT NOT NULL,
  CONSTRAINT [PK_HechosObservaciones] PRIMARY KEY ([IdObservacion]),
  CONSTRAINT [FK_HechosObservaciones_IdTema] FOREIGN KEY ([IdTema]) REFERENCES [rendimiento].[DimensionTemas] ([IdTema]),
  CONSTRAINT [FK_HechosObservaciones_IdSemestre] FOREIGN KEY ([IdSemestre]) REFERENCES [rendimiento].[DimensionSemestres] ([IdSemestre]),
  CHECK ([IdObservacion] >= 0),
  CHECK ([VecesManoLevantada] >= 0),
  CHECK ([RecursosVisitados] >= 0),
  CHECK ([AnunciosVistos] >= 0),
  CHECK ([ParticipacionesDiscusion] >= 0),
  CHECK ([IdTema] >= 0),
  CHECK ([IdSemestre] >= 0),
  CHECK ([CategoriaRendimiento] IN (N'L',N'M',N'H')),
  CHECK ([VecesManoLevantada] BETWEEN 0 AND 100),
  CHECK ([RecursosVisitados] BETWEEN 0 AND 100),
  CHECK ([AnunciosVistos] BETWEEN 0 AND 100),
  CHECK ([ParticipacionesDiscusion] BETWEEN 0 AND 100)
);
GO
