CREATE TABLE [rendimiento].[HechosNotasOficiales] (
  [CodigoAsignatura] NVARCHAR(100) NOT NULL,
  [AsignaturaPublicada] NVARCHAR(2048) NOT NULL,
  [EscuelaPublicada] NVARCHAR(2048) NOT NULL,
  [PeriodoAcademico] NVARCHAR(100) NOT NULL,
  [Inscritos] INT NOT NULL,
  [PromedioNotaPublicado] DECIMAL(12,6) NOT NULL,
  [PromedioNotaParaAnalisis] DECIMAL(12,6) NULL,
  [EstadoPromedio] NVARCHAR(2048) NOT NULL,
  [DesviacionNotaPublicada] DECIMAL(12,6) NOT NULL,
  [Aprobados] INT NOT NULL,
  [Reprobados] INT NOT NULL,
  [PorcentajeReprobacionPublicado] DECIMAL(12,6) NOT NULL,
  [Repitentes] INT NOT NULL,
  [PorcentajeRepitenciaPublicado] DECIMAL(12,6) NOT NULL,
  [Institucion] NVARCHAR(2048) NOT NULL,
  [Sede] NVARCHAR(2048) NOT NULL,
  [IdentificadorFuente] NVARCHAR(100) NOT NULL,
  [PaginaArchivoFuente] INT NOT NULL,
  [TablaFuente] INT NOT NULL,
  CONSTRAINT [PK_HechosNotasOficiales] PRIMARY KEY ([CodigoAsignatura], [PeriodoAcademico]),
  CONSTRAINT [FK_HechosNotasOficiales_CodigoAsignatura] FOREIGN KEY ([CodigoAsignatura]) REFERENCES [rendimiento].[DimensionAsignaturasOficiales] ([CodigoAsignatura]),
  CONSTRAINT [FK_HechosNotasOficiales_PeriodoAcademico] FOREIGN KEY ([PeriodoAcademico]) REFERENCES [rendimiento].[DimensionPeriodosNotas] ([PeriodoAcademico]),
  CONSTRAINT [FK_HechosNotasOficiales_IdentificadorFuente] FOREIGN KEY ([IdentificadorFuente]) REFERENCES [rendimiento].[DimensionFuentesOficiales] ([IdentificadorFuente]),
  CHECK ([Inscritos] >= 0),
  CHECK ([Aprobados] >= 0),
  CHECK ([Reprobados] >= 0),
  CHECK ([PorcentajeReprobacionPublicado] BETWEEN 0 AND 100),
  CHECK ([Repitentes] >= 0),
  CHECK ([PorcentajeRepitenciaPublicado] BETWEEN 0 AND 100),
  CHECK ([PaginaArchivoFuente] >= 0),
  CHECK ([TablaFuente] >= 0),
  CHECK ([Inscritos] > 0),
  CHECK ([Inscritos] = [Aprobados] + [Reprobados]),
  CHECK ([PromedioNotaPublicado] BETWEEN 0 AND 5),
  CHECK ([DesviacionNotaPublicada] >= 0),
  CHECK (([PromedioNotaPublicado] = 0 AND [PromedioNotaParaAnalisis] IS NULL) OR ([PromedioNotaPublicado] > 0 AND [PromedioNotaParaAnalisis] IS NOT NULL AND [PromedioNotaParaAnalisis] = [PromedioNotaPublicado]))
);
GO
