CREATE TABLE [rendimiento].[HechosDesercionOficial] (
  [CodigoFacultad] NVARCHAR(100) NOT NULL,
  [FacultadPublicada] NVARCHAR(2048) NOT NULL,
  [CohorteIngreso] NVARCHAR(100) NOT NULL,
  [PeriodoSeguimiento] NVARCHAR(100) NOT NULL,
  [MatriculadosIniciales] INT NOT NULL,
  [MatriculadosSeguimiento] INT NOT NULL,
  [ReservasCupo] INT NOT NULL,
  [Graduados] INT NOT NULL,
  [GraduadosMatriculados] INT NOT NULL,
  [DesertoresNetos] INT NOT NULL,
  [PorcentajeDesercionPublicado] DECIMAL(12,6) NOT NULL,
  [TransferenciasSalida] INT NOT NULL,
  [TransferenciasEntrada] INT NOT NULL,
  [Institucion] NVARCHAR(2048) NOT NULL,
  [Sede] NVARCHAR(2048) NOT NULL,
  [Metodologia] NVARCHAR(2048) NOT NULL,
  [IdentificadorFuente] NVARCHAR(100) NOT NULL,
  [PaginaArchivoFuente] INT NOT NULL,
  [PaginaImpresaFuente] INT NOT NULL,
  [TablaFuente] INT NOT NULL,
  CONSTRAINT [PK_HechosDesercionOficial] PRIMARY KEY ([CodigoFacultad], [CohorteIngreso]),
  CONSTRAINT [FK_HechosDesercionOficial_CodigoFacultad] FOREIGN KEY ([CodigoFacultad]) REFERENCES [rendimiento].[DimensionFacultadesOficiales] ([CodigoFacultad]),
  CONSTRAINT [FK_HechosDesercionOficial_CohorteIngreso] FOREIGN KEY ([CohorteIngreso]) REFERENCES [rendimiento].[DimensionCohortesDesercion] ([CohorteIngreso]),
  CONSTRAINT [FK_HechosDesercionOficial_IdentificadorFuente] FOREIGN KEY ([IdentificadorFuente]) REFERENCES [rendimiento].[DimensionFuentesOficiales] ([IdentificadorFuente]),
  CONSTRAINT [FK_Desercion_CohorteSeguimiento] FOREIGN KEY ([CohorteIngreso], [PeriodoSeguimiento]) REFERENCES [rendimiento].[DimensionCohortesDesercion] ([CohorteIngreso], [PeriodoSeguimiento]),
  CHECK ([MatriculadosIniciales] >= 0),
  CHECK ([MatriculadosSeguimiento] >= 0),
  CHECK ([ReservasCupo] >= 0),
  CHECK ([Graduados] >= 0),
  CHECK ([GraduadosMatriculados] >= 0),
  CHECK ([DesertoresNetos] >= 0),
  CHECK ([PorcentajeDesercionPublicado] BETWEEN 0 AND 100),
  CHECK ([TransferenciasSalida] >= 0),
  CHECK ([TransferenciasEntrada] >= 0),
  CHECK ([PaginaArchivoFuente] >= 0),
  CHECK ([PaginaImpresaFuente] >= 0),
  CHECK ([TablaFuente] >= 0),
  CHECK ([MatriculadosIniciales] > 0),
  CHECK ([DesertoresNetos] = [MatriculadosIniciales] - [MatriculadosSeguimiento] - [ReservasCupo] - ([Graduados] - [GraduadosMatriculados]))
);
GO
