CREATE VIEW [rendimiento].[EDA_TemaSemestreRendimiento] AS
SELECT t.[Tema], s.[CodigoSemestre], h.[CategoriaRendimiento], COUNT(*) AS [Observaciones]
FROM [rendimiento].[HechosObservaciones] AS h
JOIN [rendimiento].[DimensionTemas] AS t ON t.[IdTema] = h.[IdTema]
JOIN [rendimiento].[DimensionSemestres] AS s ON s.[IdSemestre] = h.[IdSemestre]
GROUP BY t.[Tema], s.[CodigoSemestre], h.[CategoriaRendimiento];
GO
CREATE ROLE [rendimiento_reader];
GRANT SELECT ON SCHEMA::[rendimiento] TO [rendimiento_reader];
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionTemas]) <> 12 THROW 51001, 'Unexpected row count in DimensionTemas', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionSemestres]) <> 2 THROW 51001, 'Unexpected row count in DimensionSemestres', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionAsignaturasOficiales]) <> 1255 THROW 51001, 'Unexpected row count in DimensionAsignaturasOficiales', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionPeriodosNotas]) <> 2 THROW 51001, 'Unexpected row count in DimensionPeriodosNotas', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionFacultadesOficiales]) <> 5 THROW 51001, 'Unexpected row count in DimensionFacultadesOficiales', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionCohortesDesercion]) <> 2 THROW 51001, 'Unexpected row count in DimensionCohortesDesercion', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[DimensionFuentesOficiales]) <> 3 THROW 51001, 'Unexpected row count in DimensionFuentesOficiales', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[HechosObservaciones]) <> 480 THROW 51001, 'Unexpected row count in HechosObservaciones', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[HechosNotasOficiales]) <> 1977 THROW 51001, 'Unexpected row count in HechosNotasOficiales', 1;
GO
IF (SELECT COUNT_BIG(*) FROM [rendimiento].[HechosDesercionOficial]) <> 10 THROW 51001, 'Unexpected row count in HechosDesercionOficial', 1;
GO
COMMIT TRANSACTION;
